,\n        \"@deepseek-ai/dsh-skill\": \"0.2.1-alpha.1\",\n        \"@deepseek-ai/dsh-system-prompt\": \"0.2.1-alpha.1\",\n        \"@deepseek-ai/dsh-tools\": \"0.2.1-alpha.1\",\n        \"@deepseek-ai/dsh-util-values\": \"0.2.1-alpha.1\",\n        \"@radix-ui/react-alert-dialog\": \"1.1.15\",\n        \"@radix-ui/react-checkbox\": \"1.3.3\",\n        \"@radix-ui/react-dialog\": \"1.1.15\",\n        \"@radix-ui/react-dropdown-menu\": \"2.1.16\",\n        \"@radix-ui/react-label\": \"2.1.7\",\n        \"@radix-ui/react-progress\": \"1.1.7\",\n        \"@radix-ui/react-select\": \"2.2.6\",\n        \"@radix-ui/react-separator\": \"1.1.7\",\n        \"@radix-ui/react-slider\": \"1.3.6\",\n        \"@radix-ui/react-slot\": \"1.2.3\",\n        \"@radix-ui/react-switch\": \"1.2.6\",\n        \"@radix-ui/react-tabs\": \"1.1.13\",\n        \"@radix-ui/react-tooltip\": \"1.2.8\",\n        \"@sparkjsdev/spark\": \"2.1.0\",\n        \"@types/node\": \"20.19.13\",\n        \"@types/react\": \"^18.3.1\",\n        \"@types/react-dom\": \"^18.3.1\",\n        \"@xyflow/react\": \"12.9.0\",\n        \"class-variance-authority\": \"0.7.1\",\n        \"clsx\": \"2.1.1\",\n        \"lucide-react\": \"0.544.0\",\n        \"masonic\": \"4.1.0\",\n        \"react\": \"^18.3.1\",\n        \"react-dom\": \"^18.3.1\",\n        \"react-hot-toast\": \"2.6.0\",\n        \"tailwind-merge\": \"3.3.1\",\n        \"three\": \"0.183.2\",\n        \"tongflow-studio\": \"workspace:*\",\n        \"tsdown\": \"0.22.14\",\n        \"tw-animate-css\": \"1.3.8\",\n        \"typescript\": \"5\",\n        \"use-intl\": \"4.8.3\",\n        \"uuid\": \"13.0.0\",\n        \"vitest\": \"4.1.5\",\n        \"zustand\": \"5.0.8\"\n    }\n}\n"
