      "path": "packages/dsh-tongflow/src/tools.ts",
      "content": "/**\n * The studio's tongflow_* tools on dsh's tool registry. The tools themselves\n * are host-neutral (`tongflow-studio`); this file gives each call what dsh\n * has to offer: the agent's session and cwd, the attachment store for images,\n * the llm runtime's model catalog, and the job registry for background runs.\n */\nimport type { Context } from \"@deepseek-ai/cordis\";\nimport type {\n    AttachmentStore,\n    ImageAttachmentRef,\n} from \"@deepseek-ai/dsh-attachment\";\nimport type { JobHandle, JobRegistry, JobSpec } from \"@deepseek-ai/dsh-jobs\";\nimport type { ContentBlock, LlmRuntime } from \"@deepseek-ai/dsh-llm\";\nimport {\n    defineTool,\n    type ParameterSchemaSpec,\n    type ToolDefinition,\n    type ToolRunContext,\n} from \"@deepseek-ai/dsh-tools\";\nimport type { JsonValue } from \"@deepseek-ai/dsh-util-values\";\nimport {\n    allTools,\n    formatEvent,\n    type RunRecord,\n    runResult,\n    type ToolCall,\n    type ToolEnv,\n    type ToolSpec,\n} from \"tongflow-studio\";\n\ndeclare module \"@deepseek-ai/dsh-jobs\" {\n    interface JobKindMap {\n        tongflow: \"tongflow\";\n    }\n}\n\n/**\n * Whether the model this call runs under accepts image content. Mirrors the\n * llm runtime's own predicate: it only projects images away for a model that\n * *declares* modalities without \"image\", so an undeclared catalog stays\n * image-capable here too. Unknown agent or absent llm service means \"assume it\n * takes images\" — the runtime degrades gracefully either way, and guessing the\n * other direction would spend a plugin run on every look.\n */\nexport async function modelTakesImages(\n    ctx: Context,\n    exec: ToolRunContext,\n): Promise<boolean> {\n    const llm = ctx.get(\"llm\") as LlmRuntime | undefined;\n    const { provider, model } = exec.agent?.options ?? {};\n    if (!llm || !provider || !model) return true;\n    try {\n        const info = await llm.resolveModelInfo(provider, model, exec.signal);\n        return (\n            info.inputModalities === undefined ||\n            info.inputModalities.includes(\"image\")\n        );\n    } catch {\n        return true;\n    }\n}\n\n/**\n * Background job spec for a workflow run, valid on both job APIs we support.\n * dsh >= 0.1.7 keys ownership by session id, passes a JobHandle to `run` for\n * streaming output, and returns the final value as `result`. dsh 0.1.5 took\n * the live Agent as owner, pulled `readOutput()`, and read `output`. The newer\n * registry is the one exposing `events` (0.1.5 had `onJobDone`).\n */\nfunction backgroundJobSpec(\n    jobs: JobRegistry,\n    agent: ToolRunContext[\"agent\"],\n    workflow: string,\n    record: RunRecord,\n): JobSpec {\n    const modern = \"events\" in jobs;\n    const owner = agent ? { owner: modern ? agent.id : agent } : {};\n    return {\n        kind: \"tongflow\",\n        label: `tongflow ${workflow}`,\n        ...owner,\n        run: (job?: JobHandle) => {\n            let stop = () => {};\n            if (job) {\n                const append = (text: string) => {\n                    if (text) job.append(`${text}\\n`);\n                };\n                append(record.readOutput());\n                stop = record.subscribe((event) => append(formatEvent(event)));\n            }\n            return {\n                cancel: (reason?: string) => record.cancel(reason),\n                done: record.done.then((r) => {\n                    stop();\n                    const final = JSON.stringify(runResult(r), null, 2);\n                    return {\n                        status:\n                            r.summary.status === \"completed\"\n                                ? (\"completed\" as const)\n                                : r.summary.status === \"cancelled\"\n                                  ? (\"killed\" as const)\n                                  : (\"failed\" as const),\n                        ...(r.error ? { detail: r.error } : {}),\n                        result: final,\n                        output: final,\n                    };\n                }),\n                readOutput: () => record.readOutput(),\n            };\n        },\n    } as JobSpec;\n}\n\n/** One dsh execution as the neutral tools see it; absent services stay absent so the tools degrade. */\nfunction toolCall(ctx: Context, exec: ToolRunContext): ToolCall {\n    const attachments = ctx.get(\"attachments\") as AttachmentStore | undefined;\n    const jobs = ctx.get(\"jobs\") as JobRegistry | undefined;\n    const cwd = exec.agent?.session.header.cwd;\n    return {\n        signal: exec.signal,\n        ...(exec.agent?.id ? { sessionId: String(exec.agent.id) } : {}),\n        ...(cwd ? { cwd } : {}),\n        takesImages: () => modelTakesImages(ctx, exec),\n        ...(attachments\n            ? {\n                  showImage: async (image) => {\n                      const attachment = await attachments.saveImage(image);\n                      return {\n                          attachment: attachment as unknown as JsonValue,\n                          width: attachment.width,\n                          height: attachment.height,\n                      };\n                  },\n              }\n            : {}),\n        ...(jobs\n            ? {\n                  startBackground: (workflow, record) =>\n                      String(\n                          jobs.start(\n                              backgroundJobSpec(\n                                  jobs,\n                                  exec.agent,\n                                  workflow,\n                                  record,\n                              ),\n                          ),\n                      ),\n              }\n            : {}),\n    };\n}\n\nfunction text(value: unknown): ContentBlock[] {\n    return [\n        {\n            type: \"text\",\n            text:\n                typeof value === \"string\"\n                    ? value\n                    : JSON.stringify(value, null, 2),\n        },\n    ];\n}\n\n/** Text for the model, plus the image when the value carries one (tongflow_look). */\nfunction render(_args: unknown, value: JsonValue): ContentBlock[] {\n    const val = value as {\n        attachment?: ImageAttachmentRef;\n        summary?: string;\n    } | null;\n    if (!val || typeof val !== \"object\" || !val.attachment) return text(value);\n    return [\n        ...text(val.summary ?? JSON.stringify(value)),\n        { type: \"image\", attachment: val.attachment },\n    ];\n}\n\nfunction dshTool(ctx: Context, spec: ToolSpec): ToolDefinition {\n    return defineTool({\n        name: spec.name,\n        description: spec.description,\n        parameters: spec.parameters as ParameterSchemaSpec,\n        output: {\n            schema: { type: spec.returns === \"string\" ? \"string\" : \"json\" },\n            render,\n        },\n        execute: (args, exec) =>\n            spec.execute(args as never, toolCall(ctx, exec)) as Promise<never>,\n    });\n}\n\n/** Register every tongflow_* tool on ctx.tools; registrations are effects (disposed on unload). */\nexport function registerTools(ctx: Context, env: ToolEnv): void {\n    for (const spec of allTools(env)) {\n        const tool = dshTool(ctx, spec);\n        ctx.effect(\n            () => ctx.tools.register(tool),\n            `dsh-tongflow: tool ${tool.name}`,\n        );\n    }\n}\n"
    },
    {
      "path": "packages/dsh-tongflow/src/index.ts",
      "content": "/**\n * dsh-tongflow — host (Node) half.\n *\n * A Cordis plugin mounted by the dsh Loader. It stands up the Studio (paths,\n * python bootstrap, plugin registry, run manager) and registers, as effects:\n * the tongflow_* agent tools, packaged skills, a short system-prompt section\n * and the HTTP routes the embedded canvas / studio UI talk to.\n */\n\nimport { join } from \"node:path\";\nimport type { Context } from \"@deepseek-ai/cordis\";\nimport type {} from \"@deepseek-ai/dsh-host-webserver\";\nimport type {} from \"@deepseek-ai/dsh-skill\";\nimport type {} from \"@deepseek-ai/dsh-system-prompt\";\nimport type {} from \"@deepseek-ai/dsh-tools\";\nimport {\n    createRouteHandler,\n    routePrefix,\n    STUDIO_LANGUAGE,\n    STUDIO_RULES,\n    Studio,\n    StudioApi,\n} from \"tongflow-studio\";\nimport { installActivation } from \"./activation.ts\";\nimport { Config, resolveDshHome } from \"./config.ts\";\n\nexport const name = \"dsh-tongflow\";\n\n/** The tool registry and agent registry are the hard requirements; other seams attach when they mount. */\nexport const inject = [\"tools\", \"agents\"];\n\nexport { Config };\nexport type { Config as TongflowConfig } from \"./config.ts\";\n\nexport function apply(ctx: Context, config: Config): void {\n    const log = (line: string) => ctx.logger?.info?.(line);\n    const studio = new Studio({\n        config: {\n            ...config,\n            studioRoot:\n                config.studioRoot?.trim() || join(resolveDshHome(), \"tongflow\"),\n        },\n        log,\n    });\n    const api = new StudioApi(studio);\n    void studio.init().catch((error: unknown) => {\n        ctx.logger?.warn?.(\n            `dsh-tongflow: studio init failed: ${error instanceof Error ? error.message : String(error)}`,\n        );\n    });\n\n    // Tools / prompt / skills attach per agent, only for studio sessions\n    // (first message starts with \"@tongflow\", or the cwd is a studio project).\n    installActivation(ctx, {\n        studio,\n        env: { studio, api },\n        systemSection: SYSTEM_SECTION,\n    });\n\n    ctx.inject([\"webServer\"], (webCtx) => {\n        const handler = createRouteHandler({\n            studio,\n            api,\n            prefix: config.httpPrefix,\n        });\n        webCtx.effect(\n            () =>\n                webCtx.webServer.register({\n                    kind: \"prefix\",\n                    path: routePrefix(config.httpPrefix),\n                    handler,\n                }),\n            \"dsh-tongflow: http routes\",\n        );\n    });\n}\n\nconst SYSTEM_SECTION = `${STUDIO_RULES} Load the \"tongflow-studio\" skill for the full method.\nWhat the user sees (say this, never invent panels): the Studio panel next to the chat shows a project selector, the project's folder tree (a workflow row expands to the files it generated) and a preview area — clicking any file previews or edits it, clicking a .tongflow.json opens it on the canvas. To point at a result say e.g. \"在右侧面板:characters → mei → mei_ref.02.png\" (the panel follows the project you work in). Never give absolute file paths as the way to view something.\n${STUDIO_LANGUAGE}`;\n"
    },
    {
      "path": "packages/tongflow-studio/src/tools/run-tools.ts",
      "content": "/**\n * Execution & perception tools: run a workflow (foreground or in the\n * background), look at a generated image (handed to the host as an image when\n * the session's model takes images, otherwise described through TongFlow's own\n * image-describe slot), perceive video/audio through TongFlow's own\n * describe / transcribe slots, and manage plugins.\n */\nimport { execFile as execFileCb } from \"node:child_process\";\nimport { readFile, stat } from \"node:fs/promises\";\nimport { extname, join } from \"node:path\";\nimport { promisify } from \"node:util\";\nimport type { RunRecord } from \"../engine/runs.ts\";\nimport { formatEvent } from \"../engine/runs.ts\";\nimport { modalityOfExt } from \"../shared/types.ts\";\nimport {\n    type Json,\n    type ToolCall,\n    type ToolImage,\n    type ToolSpec,\n    tool,\n} from \"./spec.ts\";\nimport {\n    compact,\n    errorMessage,\n    PROJECT_PARAM,\n    resolveProjectId,\n    type ToolEnv,\n} from \"./support.ts\";\n\nconst execFile = promisify(execFileCb);\n\n/**\n * The clone URL as something a person or `web_fetch` can open: git remotes\n * carry a `.git` suffix and sometimes an `scp`-style host, neither of which\n * belongs in a link. A non-GitHub or already-clean URL passes through.\n */\nexport function browsableRepo(gitUrl: string): string {\n    return gitUrl.replace(/^git@([^:]+):/, \"https://$1/\").replace(/\\.git$/, \"\");\n}\n\n/**\n * A plugin's own README, when the clone shipped one. Only the path travels in\n * the catalog: the agent reads the file when it needs to choose between\n * plugins, set an unfamiliar model, or understand a failure. An installed\n * plugin is not a new trust surface — its code already runs on this machine.\n */\nexport async function pluginReadme(\n    pluginsDir: string,\n    id: string,\n): Promise<{ readme?: string }> {\n    const path = join(pluginsDir, id, \"README.md\");\n    try {\n        if ((await stat(path)).isFile()) return { readme: path };\n    } catch {\n        // Not every plugin ships one; absence is normal, not an error.\n    }\n    return {};\n}\n\n/** One TongFlow describe/transcribe slot run over a local media file. */\ninterface SlotDescription {\n    ok: boolean;\n    feature: string;\n    pluginId?: string;\n    answer?: string;\n    error?: string;\n    log?: string[];\n    raw?: unknown;\n    /** Set instead of running when the slot's plugin bills the user. */\n    needs_confirmation?: true;\n    billing?: string;\n    note?: string;\n}\n\n/**\n * What `tongflow_look` says when this session's model cannot see the asset.\n * A free plugin has already described it; a billing one has not run, and the\n * agent is told to ask the user and go through `tongflow_perceive`, the one\n * tool that carries the confirmation flag.\n */\nfunction blindSummary(\n    head: string,\n    kind: \"image\" | \"video\",\n    described: SlotDescription,\n): string {\n    const blind = `${head}. This session's model does not take images`;\n    if (described.ok)\n        return `${blind}, so it was described by ${described.pluginId} instead of shown:\\n${described.answer}`;\n    if (described.needs_confirmation)\n        return `${blind}, and describing it would run ${described.pluginId}, which bills you (${described.billing}: ${described.note}). Tell the user what it costs, ask, and then call tongflow_perceive with user_confirmed=true — or switch this session to a vision-capable model.`;\n    return `${blind} and it could not be described (${described.error}). Switch to a vision-capable model, or install a plugin for the ${kind}-describe slot.`;\n}\n\n/**\n * Understand a media file through TongFlow's own describe / transcribe slots.\n * Shared by `tongflow_perceive` and by `tongflow_look`'s fallback for a model\n * that does not take images.\n */\nexport async function describeViaSlot(\n    env: ToolEnv,\n    pid: string,\n    feature: string,\n    prompt: Record<string, unknown>,\n    pluginId?: string,\n    confirmed?: boolean,\n): Promise<SlotDescription> {\n    const { registry } = await env.api.registry();\n    const chosen = pluginId ?? registry.nodePluginMap[feature]?.[0];\n    if (!chosen)\n        return {\n            ok: false,\n            feature,\n            error: `no installed plugin implements ${feature}; install one (e.g. tongflow-api-gemini or tongflow-modal-qwen38) with tongflow_plugins_install`,\n        };\n    // Understanding a file is a plugin run like any other: when it bills the\n    // user, it needs their yes first, exactly like tongflow_workflow_run.\n    if (!confirmed) {\n        const { billing, note } = await env.api.pluginBilling(chosen);\n        if (billing !== \"local\")\n            return {\n                ok: false,\n                feature,\n                pluginId: chosen,\n                needs_confirmation: true,\n                billing,\n                note,\n            };\n    }\n    const record = await env.api.startCanvasRun(pid, {\n        feature,\n        pluginId: chosen,\n        prompt,\n        nodeId: \"perceive\",\n    });\n    await record.done;\n    if (record.summary.status !== \"completed\")\n        return {\n            ok: false,\n            feature,\n            pluginId: chosen,\n            error: record.error ?? \"perception run failed\",\n            log: record.events.slice(-10).map(formatEvent),\n        };\n    const texts = record.outcome?.texts ?? {};\n    const answer = Object.values(texts).flat().join(\"\\n\").trim();\n    return {\n        ok: true,\n        feature,\n        pluginId: chosen,\n        answer: answer || \"(empty answer)\",\n        raw: record.outcome?.result.outputs,\n    };\n}\n\nconst WORKFLOW_PARAM = {\n    type: \"string\",\n    required: true,\n    description:\n        \"Workflow file, project-relative, e.g. 'characters/mei/mei_ref' or 'characters/mei/mei_ref.tongflow.json'.\",\n} as const;\n\nconst IMAGE_MIME: Record<string, ToolImage[\"mediaType\"]> = {\n    png: \"image/png\",\n    jpg: \"image/jpeg\",\n    jpeg: \"image/jpeg\",\n    webp: \"image/webp\",\n    gif: \"image/gif\",\n};\n\n/** A finished (or failed) run as the agent reads it. */\nexport function runResult(record: RunRecord): Json {\n    const s = record.summary;\n    return compact({\n        runId: s.runId,\n        status: s.status,\n        ...(s.error ? { error: s.error } : {}),\n        no: record.outcome?.no ?? 0,\n        files: s.files.map((f) => f.key),\n        texts: record.outcome?.texts ?? {},\n        loose: record.outcome?.loose ?? [],\n        nodes: s.nodes,\n        log: record.events.slice(-30).map(formatEvent).filter(Boolean),\n    });\n}\n\nexport function runTools(env: ToolEnv): ToolSpec[] {\n    const { api, studio } = env;\n    return [\n        tool({\n            name: \"tongflow_workflow_run\",\n            description:\n                \"Execute a workflow file with the TongFlow engine. Its outputs land next to the file as <name>.NN.<ext> (NN = this run's number; a run never overwrites earlier outputs) and the run is logged in <name>.runs.json. \" +\n                \"Media generation takes seconds to minutes; use run_in_background for long jobs (video, batches) and continue working — check on it with tongflow_run_status. \" +\n                \"After a run, inspect the result with tongflow_look (images) or tongflow_perceive (video/audio) before moving on; if it is off, fix the workflow and run again. \" +\n                \"BILLING CHECKPOINT: a run that uses a paid plugin (API key billing or Modal GPU time) needs the user's yes EVERY time. Without user_confirmed=true this tool does not run — it returns needs_confirmation with the plugins, how each is billed, whether keys are set, available models and alternatives. Tell the user in plain words what will run and what it costs, ask, and only after they agree in this conversation call again with user_confirmed=true. Never set it on your own; nothing is remembered between runs.\",\n            parameters: {\n                project: PROJECT_PARAM,\n                workflow: WORKFLOW_PARAM,\n                inputs: {\n                    type: \"object\",\n                    additionalProperties: true,\n                    description:\n                        \"input name → text | file path (relative to the workflow file or the project root) | URL | array of those. Only for workflows that left inputs open.\",\n                },\n                note: {\n                    type: \"string\",\n                    description:\n                        \"Why this run / what changed (recorded in provenance).\",\n                },\n                run_in_background: {\n                    type: \"boolean\",\n                    description:\n                        \"Return immediately with the run id; poll with tongflow_run_status (a host with a job runtime also returns a job id and notifies you when it completes).\",\n                },\n                user_confirmed: {\n                    type: \"boolean\",\n                    description:\n                        \"Set to true ONLY after the user explicitly agreed, in this conversation, to this run and its billing (the plugins / models listed in the needs_confirmation answer). Required whenever the workflow uses a paid plugin.\",\n                },\n            },\n            async execute(args, call) {\n                const pid = await resolveProjectId(env, call, args.project);\n                if (!args.user_confirmed) {\n                    const paid = await api.paidPlugins(pid, args.workflow);\n                    if (paid.length > 0) {\n                        return compact({\n                            ok: false,\n                            needs_confirmation: true,\n                            plugins: paid,\n                            hint: \"This run costs money. Tell the user which plugin(s) / model(s) will run and how they are billed (mention alternatives when there are any, and missing API keys), ask whether to go ahead, and only after they say yes call again with user_confirmed=true. Ask every time; do not assume a previous yes still holds.\",\n                        });\n                    }\n                }\n                const record = await api.startRun({\n                    projectId: pid,\n                    workflowKey: args.workflow,\n                    ...(args.inputs\n                        ? { inputs: args.inputs as Record<string, unknown> }\n                        : {}),\n                    ...(args.note ? { note: args.note } : {}),\n                });\n                if (args.run_in_background) {\n                    const runId = record.summary.runId;\n                    if (call.startBackground)\n                        return compact({\n                            kind: \"background\",\n                            jobId: call.startBackground(args.workflow, record),\n                            runId,\n                            hint: \"poll with job_output or wait for the completion notice; then tongflow_look the new file\",\n                        });\n                    return compact({\n                        kind: \"background\",\n                        runId,\n                        hint: `poll with tongflow_run_status({ runId: \"${runId}\" }) until it is no longer running; then tongflow_look the new file`,\n                    });\n                }\n                const stop = call.progress\n                    ? record.subscribe((event) => {\n                          const line = formatEvent(event);\n                          if (line) call.progress?.(line);\n                      })\n                    : () => {};\n                const finished = await Promise.race([\n                    record.done,\n                    new Promise<never>((_, reject) =>\n                        call.signal.addEventListener(\n                            \"abort\",\n                            () => reject(new Error(\"cancelled\")),\n                            { once: true },\n                        ),\n                    ),\n                ])\n                    .catch((error) => {\n                        record.cancel(errorMessage(error));\n                        throw error;\n                    })\n                    .finally(stop);\n                return runResult(finished);\n            },\n        }),\n        tool({\n            name: \"tongflow_run_status\",\n            description:\n                \"Status, node progress and log of a run (or the recent runs of a project).\",\n            parameters: {\n                project: PROJECT_PARAM,\n                runId: {\n                    type: \"string\",\n                    description:\n                        \"Run id from tongflow_workflow_run; omit to list recent runs.\",\n                },\n            },\n            async execute(args, call) {\n                if (args.runId) {\n                    const r = api.getRun(args.runId);\n                    if (!r)\n                        return {\n                            ok: false,\n                            error: `unknown run ${args.runId}`,\n                        };\n                    return runResult(r);\n                }\n                const pid = await resolveProjectId(env, call, args.project);\n                return compact(api.listRuns(pid).slice(0, 20));\n            },\n        }),\n        tool({\n            name: \"tongflow_look\",\n            description:\n                \"Look at an asset. Images come back as an image you can see, videos as a contact sheet of sampled frames plus duration/resolution. \" +\n                \"When this session's model does not take images, both are routed through TongFlow's describe slots instead and come back as text, saying so — so a look is never silently blind. \" +\n                \"Audio returns metadata only — use tongflow_perceive for content. Takes a project-relative path (e.g. 'characters/mei/mei_ref.02.png').\",\n            parameters: {\n                project: PROJECT_PARAM,\n                ref: {\n                    type: \"string\",\n                    required: true,\n                    description: \"Project-relative path of the file.\",\n                },\n                frames: {\n                    type: \"integer\",\n                    description:\n                        \"Frames in the video contact sheet (default 9, max 16).\",\n                },\n            },\n            async execute(args, call) {\n                const pid = await resolveProjectId(env, call, args.project);\n                const path = await resolveToFile(env, pid, args.ref);\n                const ext = extname(path).slice(1).toLowerCase();\n                const modality = modalityOfExt(ext);\n                const st = await stat(path);\n                if (modality === \"image\") {\n                    const mime = IMAGE_MIME[ext];\n                    if (!mime)\n                        return compact({\n                            summary: `${args.ref}: ${ext} image (${st.size} bytes) — unsupported for inline viewing (png/jpg/webp/gif only)`,\n                        });\n                    if (!call.showImage)\n                        return compact({\n                            summary: `${args.ref}: image ${st.size} bytes at ${path} (this host cannot show images inline)`,\n                        });\n                    if (!(await takesImages(call))) {\n                        const described = await describeViaSlot(\n                            env,\n                            pid,\n                            \"image-describe\",\n                            {\n                                image: path,\n                                text: \"Describe this image in detail.\",\n                            },\n                        );\n                        return compact({\n                            ...described,\n                            summary: blindSummary(\n                                `${args.ref}: ${st.size} bytes`,\n                                \"image\",\n                                described,\n                            ),\n                            path,\n                        });\n                    }\n                    const shown = await call.showImage({\n                        data: new Uint8Array(await readFile(path)),\n                        mediaType: mime,\n                        name: path.split(\"/\").pop(),\n                    });\n                    const size =\n                        shown.width && shown.height\n                            ? `, ${shown.width}×${shown.height}`\n                            : \"\";\n                    return compact({\n                        summary: `${args.ref} → ${st.size} bytes${size}`,\n                        attachment: shown.attachment,\n                        path,\n                    });\n                }\n                if (modality === \"video\") {\n                    const probe = await ffprobe(path).catch((e) => ({\n                        error: errorMessage(e),\n                    }));\n                    if (!call.showImage)\n                        return compact({\n                            summary: `${args.ref}: video ${st.size} bytes`,\n                            probe,\n                        });\n                    if (!(await takesImages(call))) {\n                        const described = await describeViaSlot(\n                            env,\n                            pid,\n                            \"video-describe\",\n                            {\n                                video: path,\n                                text: \"Describe this video in detail: subjects, action, camera, continuity issues.\",\n                            },\n                        );\n                        return compact({\n                            ...described,\n                            summary: blindSummary(\n                                `${args.ref}: video ${st.size} bytes; ${JSON.stringify(probe)}`,\n                                \"video\",\n                                described,\n                            ),\n                            probe,\n                        });\n                    }\n                    try {\n                        const sheet = await contactSheet(\n                            path,\n                            Math.min(Math.max(args.frames ?? 9, 1), 16),\n                            studio.paths.tmp,\n                        );\n                        const shown = await call.showImage({\n                            data: new Uint8Array(await readFile(sheet)),\n                            mediaType: \"image/jpeg\",\n                            name: \"contact-sheet.jpg\",\n                        });\n                        return compact({\n                            summary: `${args.ref}: video ${st.size} bytes; ${JSON.stringify(probe)}. Contact sheet of ${args.frames ?? 9} frames follows (left→right, top→bottom).`,\n                            probe,\n                            attachment: shown.attachment,\n                        });\n                    } catch (error) {\n                        return compact({\n                            summary: `${args.ref}: video ${st.size} bytes; ${JSON.stringify(probe)}. (contact sheet unavailable: ${errorMessage(error)}; use tongflow_perceive)`,\n                            probe,\n                        });\n                    }\n                }\n                if (modality === \"audio\") {\n                    const probe = await ffprobe(path).catch((e) => ({\n                        error: errorMessage(e),\n                    }));\n                    return compact({\n                        summary: `${args.ref}: audio ${st.size} bytes; ${JSON.stringify(probe)}. Use tongflow_perceive to transcribe / describe.`,\n                        probe,\n                    });\n                }\n                if (modality === \"text\") {\n                    const body = await readFile(path, \"utf8\");\n                    return compact({\n                        summary:\n                            body.length > 8000\n                                ? `${body.slice(0, 8000)}\\n… (${body.length} chars)`\n                                : body,\n                    });\n                }\n                return compact({\n                    summary: `${args.ref}: ${modality} file, ${st.size} bytes at ${path}`,\n                });\n            },\n        }),\n        tool({\n            name: \"tongflow_perceive\",\n            description:\n                \"Understand a video, audio or image through TongFlow's describe/transcribe slots (video-describe, audio-describe / transcribe, image-describe) using an installed plugin — this is how you review generated media the chat model cannot ingest directly. \" +\n                \"Ask a concrete question: continuity with the reference, lip sync, motion quality, whether the line was spoken correctly, etc. \" +\n                \"BILLING CHECKPOINT: this runs a plugin. When that plugin bills the user, the call returns needs_confirmation instead of running — tell the user which plugin will describe the file and how it is billed, ask, and only after they agree call again with user_confirmed=true. Ask every time. A plugin that runs locally needs no confirmation.\",\n            parameters: {\n                project: PROJECT_PARAM,\n                ref: {\n                    type: \"string\",\n                    required: true,\n                    description: \"Project-relative path of the media file.\",\n                },\n                question: {\n                    type: \"string\",\n                    description:\n                        \"What to look/listen for. Default: a detailed description (or transcript for audio).\",\n                },\n                mode: {\n                    type: \"string\",\n                    enum: [\"describe\", \"transcribe\"],\n                    description:\n                        \"For audio: 'transcribe' (default) or 'describe'.\",\n                },\n                pluginId: {\n                    type: \"string\",\n                    description:\n                        \"Force a specific plugin (default: the first installed one for the slot).\",\n                },\n                user_confirmed: {\n                    type: \"boolean\",\n                    description:\n                        \"Set to true ONLY after the user explicitly agreed, in this conversation, to this plugin running and its billing. Never set it on your own; nothing is remembered between calls.\",\n                },\n            },\n            async execute(args, call) {\n                const pid = await resolveProjectId(env, call, args.project);\n                const path = await resolveToFile(env, pid, args.ref);\n                const modality = modalityOfExt(extname(path).slice(1));\n                let feature: string;\n                let prompt: Record<string, unknown>;\n                const question = args.question ?? \"\";\n                if (modality === \"video\") {\n                    feature = \"video-describe\";\n                    prompt = {\n                        video: path,\n                        text:\n                            question ||\n                            \"Describe this video in detail: subjects, action, camera, continuity issues.\",\n                        userPrompt: question,\n                    };\n                } else if (modality === \"audio\") {\n                    if ((args.mode ?? \"transcribe\") === \"transcribe\") {\n                        feature = \"transcribe\";\n                        prompt = {\n                            audio: path,\n                            ...(question ? { context: question } : {}),\n                        };\n                    } else {\n                        feature = \"audio-describe\";\n                        prompt = {\n                            audio: path,\n                            text: question || \"Describe this audio.\",\n                            userPrompt: question,\n                        };\n                    }\n                } else if (modality === \"image\") {\n                    feature = \"image-describe\";\n                    prompt = {\n                        image: path,\n                        text: question || \"Describe this image in detail.\",\n                        userPrompt: question,\n                    };\n                } else {\n                    return {\n                        ok: false,\n                        error: `${args.ref} is not a video/audio/image`,\n                    };\n                }\n                return compact(\n                    await describeViaSlot(\n                        env,\n                        pid,\n                        feature,\n                        prompt,\n                        args.pluginId,\n                        args.user_confirmed,\n                    ),\n                );\n            },\n        }),\n        tool({\n            name: \"tongflow_plugins_list\",\n            description:\n                \"Installed TongFlow plugins (id, name, ABI slots they implement, required env keys, the path of the plugin's own README, and its source repo) and the official plugins that can be installed, each with its repo. \" +\n                \"A plugin's README is written by whoever wrote the plugin: which models it offers and which is the default, what each env key does, resolutions and aspect ratios it accepts, and its quirks. For an INSTALLED plugin read the local `readme` — it is the clone's own file, costs nothing and is already trusted, since that plugin's code runs on this machine. \" +\n                \"For an official plugin that is NOT installed there is no local file: fetch its README at <repo>/blob/main/README.md (raw: replace github.com with raw.githubusercontent.com and drop /blob) to see what it does before suggesting the user install it. Never recommend an install from the id alone.\",\n            parameters: {},\n            async execute() {\n                const { registry, meta } = await api.registry();\n                const OFFICIAL_PLUGINS = await studio.registry.officialIds();\n                const installed = await Promise.all(\n                    Object.entries(registry.plugins).map(async ([id, p]) => ({\n                        id,\n                        name: (p as { name?: string }).name ?? id,\n                        slots: Object.keys(\n                            (\n                                p as {\n                                    methodsByNodeSlot: Record<string, unknown>;\n                                }\n                            ).methodsByNodeSlot,\n                        ),\n                        env: (meta[id]?.env ?? []).map(\n                            (e) => `${e.key}${e.required ? \"*\" : \"\"}`,\n                        ),\n                        // The path only; the file is read on demand, never\n                        // pulled into the catalog. Together the installed\n                        // READMEs run to thousands of lines.\n                        ...(await pluginReadme(studio.paths.plugins, id)),\n                        repo: browsableRepo(studio.registry.gitUrlFor(id)),\n                    })),\n                );\n                return compact({\n                    installed,\n                    // Not installed: no local README, so the repo is the only\n                    // way to find out what it does before suggesting an install.\n                    official: OFFICIAL_PLUGINS.filter(\n                        (id) => !registry.plugins[id],\n                    ).map((id) => ({\n                        id,\n                        repo: browsableRepo(studio.registry.gitUrlFor(id)),\n                    })),\n                    errors: registry.errors ?? [],\n                });\n            },\n        }),\n        tool({\n            name: \"tongflow_plugins_install\",\n            description:\n                \"Install a TongFlow plugin by official id (e.g. tongflow-api-gemini, tongflow-modal-qwen38) or git URL. Plugins run in their own Python env; API keys go into the tongflow settings.\",\n            parameters: { idOrUrl: { type: \"string\", required: true } },\n            async execute(args) {\n                const r = await api.installPlugin(args.idOrUrl);\n                const { meta } = await api.registry();\n                return compact({ ...r, env: meta[r.id]?.env ?? [] });\n            },\n        }),\n        tool({\n            name: \"tongflow_plugins_uninstall\",\n            description: \"Remove an installed TongFlow plugin.\",\n            parameters: { id: { type: \"string\", required: true } },\n            async execute(args) {\n                await api.uninstallPlugin(args.id);\n                return { ok: true };\n            },\n        }),\n    ];\n}\n\n/** Absent means \"assume it takes images\": guessing the other way would spend a plugin run on every look. */\nasync function takesImages(call: ToolCall): Promise<boolean> {\n    return call.takesImages ? call.takesImages() : true;\n}\n\nasync function resolveToFile(\n    env: ToolEnv,\n    projectId: string,\n    ref: string,\n): Promise<string> {\n    return env.api.filePath(projectId, ref);\n}\n\nasync function ffprobe(path: string): Promise<Json> {\n    const { stdout } = await execFile(\"ffprobe\", [\n        \"-v\",\n        \"error\",\n        \"-show_entries\",\n        \"format=duration:stream=codec_type,codec_name,width,height,r_frame_rate,sample_rate,channels\",\n        \"-of\",\n        \"json\",\n        path,\n    ]);\n    const parsed = JSON.parse(stdout) as {\n        format?: { duration?: string };\n        streams?: Record<string, unknown>[];\n    };\n    return compact({\n        duration: parsed.format?.duration\n            ? Number(Number(parsed.format.duration).toFixed(2))\n            : undefined,\n        streams: (parsed.streams ?? []).map((s) =>\n            Object.fromEntries(\n                Object.entries(s).filter(([, v]) => v !== undefined),\n            ),\n        ),\n    });\n}\n\n/** Sample `n` frames evenly across the video and tile them into one JPEG. */\nasync function contactSheet(\n    path: string,\n    n: number,\n    tmpDir: string,\n): Promise<string> {\n    const cols = n <= 4 ? 2 : n <= 9 ? 3 : 4;\n    const rows = Math.ceil(n / cols);\n    const out = join(\n        tmpDir,\n        `sheet-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.jpg`,\n    );\n    const probe = (await ffprobe(path)) as { duration?: number };\n    const duration = probe.duration && probe.duration > 0 ? probe.duration : 1;\n    const fps = n / duration;\n    await execFile(\"ffmpeg\", [\n        \"-v\",\n        \"error\",\n        \"-y\",\n        \"-i\",\n        path,\n        \"-vf\",\n        `fps=${fps},scale=480:-2,tile=${cols}x${rows}`,\n        \"-frames:v\",\n        \"1\",\n        \"-q:v\",\n        \"4\",\n        out,\n    ]);\n    return out;\n}\n"
    },
    {
      "path": "packages/tongflow-studio/src/api.ts",
      "content": "/**\n * StudioApi — the one service layer both the agent tools and the HTTP routes\n * call. Everything is keyed by project id; the project directory on disk is\n * the source of truth (no in-memory canvas state).\n */\nimport {\n    mkdir,\n    readdir,\n    readFile,\n    stat,\n    unlink,\n    writeFile,\n} from \"node:fs/promises\";\nimport { basename, join } from \"node:path\";\nimport {\n    type ExecuteToolContext,\n    executeGraphTool,\n    type GraphPatch,\n    KNOWN_NODE_TYPES,\n    NODE_TYPE_TO_ABI_FEATURE,\n    renderCanvas,\n    resolvedSpecForNodeType,\n    type ToolResult,\n} from \"tongflow\";\nimport {\n    categoryOf,\n    NODE_CATEGORY_ORDER,\n    type NodeCategory,\n} from \"./engine/node-categories.ts\";\nimport type { RunRequest } from \"./engine/run.ts\";\nimport type { RunRecord } from \"./engine/runs.ts\";\nimport {\n    type CanvasTaskBody,\n    singleNodeDocument,\n} from \"./engine/single-node.ts\";\nimport {\n    COMPOSED_SUFFIX,\n    type ComposeResult,\n    composeWorkflows,\n    workflowsInFolder,\n} from \"./project/compose.ts\";\nimport {\n    type CreateProjectInput,\n    createProject,\n    listProjects,\n    loadProject,\n    type ProjectRef,\n    summarize,\n} from \"./project/manifest.ts\";\nimport { listOutputs, readRunsLog, runsLogKey } from \"./project/outputs.ts\";\nimport {\n    fromProjectKey,\n    normalizeKey,\n    RUNS_DIR,\n    toProjectKey,\n    WORKFLOW_EXT,\n} from \"./project/paths.ts\";\nimport {\n    canvasView,\n    deleteWorkflowFile,\n    hydrateStore,\n    isWorkflowKey,\n    listWorkflows,\n    normalizeWorkflowKey,\n    readWorkflowFile,\n    saveWorkflowFile,\n    summarizeWorkflow,\n    type WorkflowDocument,\n    workflowHash,\n} from \"./project/workflow-file.ts\";\nimport type {\n    OutputInfo,\n    PluginBilling,\n    PluginConfirmation,\n    ProjectSummary,\n    TreeNode,\n    WorkflowFileMeta,\n    WorkflowSummary,\n} from \"./shared/types.ts\";\nimport { modalityOfExt } from \"./shared/types.ts\";\nimport type { Studio } from \"./studio.ts\";\nimport { exists, writeFileAtomic } from \"./util/fsx.ts\";\n\n/** Where a folder's composed workflow lives: inside that folder, named after it. */\nfunction composedKeyForFolder(folderKey: string): string {\n    const dir = normalizeKey(folderKey);\n    const name = `${basename(dir || \"project\")}${COMPOSED_SUFFIX}${WORKFLOW_EXT}`;\n    return dir ? `${dir}/${name}` : name;\n}\n\nexport class StudioApi {\n    constructor(readonly studio: Studio) {}\n\n    /* ---------------- projects ---------------- */\n\n    listProjects(): Promise<ProjectSummary[]> {\n        return listProjects(this.studio.paths.root);\n    }\n\n    async createProject(input: CreateProjectInput): Promise<ProjectSummary> {\n        const { id } = await createProject(this.studio.paths.root, {\n            locale: this.studio.config.locale,\n            ...input,\n        });\n        return summarize(await this.project(id));\n    }\n\n    project(projectId: string): Promise<ProjectRef> {\n        return loadProject(this.studio.paths.root, projectId);\n    }\n\n    async projectSummary(projectId: string): Promise<ProjectSummary> {\n        return summarize(await this.project(projectId));\n    }\n\n    /**\n     * What exists: the folder tree (as indented text), every workflow with\n     * its outputs, recent runs. This is what the agent reads first.\n     */\n    async status(projectId: string) {\n        const ref = await this.project(projectId);\n        const [summary, workflows, tree] = await Promise.all([\n            summarize(ref),\n            listWorkflows(ref.root),\n            this.tree(projectId),\n        ]);\n        return {\n            project: summary,\n            tree: renderTree(tree),\n            workflows: workflows.map((w) => ({\n                key: w.key,\n                name: w.name,\n                ...(w.description ? { description: w.description } : {}),\n                nodes: w.nodeCount,\n                inputs: w.inputs,\n                outputs: w.outputCount,\n                lastNo: w.lastNo,\n            })),\n            runs: this.studio.runs.list(projectId).slice(0, 10),\n        };\n    }\n\n    /* ---------------- workflows ---------------- */\n\n    async listWorkflows(projectId: string): Promise<WorkflowSummary[]> {\n        return listWorkflows((await this.project(projectId)).root);\n    }\n\n    async readWorkflow(\n        projectId: string,\n        key: string,\n    ): Promise<WorkflowDocument> {\n        return readWorkflowFile(\n            (await this.project(projectId)).root,\n            normalizeWorkflowKey(key),\n        );\n    }\n\n    /** The document as the canvas should see it (references anchored at the project root). */\n    async readWorkflowForCanvas(\n        projectId: string,\n        keyInput: string,\n    ): Promise<WorkflowDocument> {\n        const key = normalizeWorkflowKey(keyInput);\n        return canvasView(await this.readWorkflow(projectId, key), key);\n    }\n\n    async workflowSummary(\n        projectId: string,\n        key: string,\n    ): Promise<WorkflowSummary> {\n        return summarizeWorkflow(\n            (await this.project(projectId)).root,\n            normalizeWorkflowKey(key),\n        );\n    }\n\n    /** Create an empty workflow file, or copy another workflow — never overwrites. */\n    async newWorkflow(\n        projectId: string,\n        keyInput: string,\n        options: {\n            copyFrom?: string;\n            name?: string;\n            description?: string;\n            meta?: WorkflowFileMeta;\n        } = {},\n    ): Promise<WorkflowSummary> {\n        const ref = await this.project(projectId);\n        const key = normalizeWorkflowKey(keyInput);\n        const abs = fromProjectKey(ref.root, key);\n        if (await exists(abs))\n            throw new Error(\n                `${key} already exists — patch it, or pick another name`,\n            );\n        let doc: WorkflowDocument;\n        if (options.copyFrom) {\n            const src = await this.readWorkflow(projectId, options.copyFrom);\n            doc = { ...src, meta: { ...src.meta, ...(options.meta ?? {}) } };\n            if (options.name) doc.name = options.name;\n            if (options.description !== undefined)\n                doc.description = options.description;\n        } else {\n            doc = {\n                name: options.name ?? basename(key, WORKFLOW_EXT),\n                ...(options.description\n                    ? { description: options.description }\n                    : {}),\n                flow: { nodes: [], edges: [] },\n                meta: options.meta ?? {},\n            };\n        }\n        const store = hydrateStore(doc);\n        const registry = (await this.studio.registry.get()).registry;\n        await saveWorkflowFile(ref.root, key, store, {\n            registry,\n            meta: doc.meta,\n            name: doc.name,\n            description: doc.description ?? \"\",\n        });\n        return summarizeWorkflow(ref.root, key);\n    }\n\n    /** Run one of the tongflow graph tools (apply_graph_patch / read_canvas / validate_workflow / describe_node_type) against a file. */\n    async graphTool(\n        projectId: string,\n        keyInput: string,\n        tool: string,\n        args: Record<string, unknown>,\n    ): Promise<ToolResult & { workflow?: string; rendered?: string }> {\n        const ref = await this.project(projectId);\n        const key = normalizeWorkflowKey(keyInput);\n        const doc = await readWorkflowFile(ref.root, key);\n        const store = hydrateStore(doc);\n        const registry = (await this.studio.registry.get()).registry;\n        const context: ExecuteToolContext = {\n            registry,\n            statusByNodeId: this.nodeStatuses(projectId, key),\n        };\n        const result = executeGraphTool(store, tool, args, context);\n        if (tool === \"apply_graph_patch\") {\n            await saveWorkflowFile(ref.root, key, store, {\n                registry,\n                meta: doc.meta,\n            });\n            const state = store.getState();\n            return {\n                ...result,\n                workflow: key,\n                rendered: renderCanvas(state.nodes, state.edges, {\n                    maxText: 80,\n                }),\n            };\n        }\n        return { ...result, workflow: key };\n    }\n\n    async patchWorkflow(projectId: string, key: string, patch: GraphPatch) {\n        return this.graphTool(\n            projectId,\n            key,\n            \"apply_graph_patch\",\n            patch as unknown as Record<string, unknown>,\n        );\n    }\n\n    /** Full read: rendered canvas + inputs/outputs + generated files + validation. */\n    async describeWorkflow(projectId: string, keyInput: string) {\n        const ref = await this.project(projectId);\n        const key = normalizeWorkflowKey(keyInput);\n        const doc = await readWorkflowFile(ref.root, key);\n        const store = hydrateStore(doc);\n        const registry = (await this.studio.registry.get()).registry;\n        const validation = executeGraphTool(\n            store,\n            \"validate_workflow\",\n            {},\n            { registry },\n        );\n        const [summary, outputs] = await Promise.all([\n            summarizeWorkflow(ref.root, key),\n            listOutputs(ref.root, key),\n        ]);\n        return {\n            ok: true as const,\n            workflow: key,\n            name: doc.name,\n            description: doc.description,\n            canvas: renderCanvas(doc.flow.nodes, doc.flow.edges, {\n                maxText: 200,\n            }),\n            inputs: summary.inputs,\n            outputs: summary.outputs,\n            meta: doc.meta,\n            executable: Boolean(doc.executable),\n            exportError: doc.exportError,\n            validation,\n            hash: workflowHash(doc),\n            files: outputs.map((o) => ({\n                key: o.key,\n                no: o.no,\n                ...(o.output ? { output: o.output } : {}),\n                size: o.size,\n                mtime: o.mtime,\n                ...(o.record?.note ? { note: o.record.note } : {}),\n            })),\n        };\n    }\n\n    /**\n     * Compose small workflows (explicit list, or every workflow directly in\n     * a folder) into one big one; see project/compose.ts.\n     */\n    async composeWorkflows(\n        projectId: string,\n        options: {\n            workflows?: string[];\n            folder?: string;\n            path?: string;\n            name?: string;\n        },\n    ): Promise<ComposeResult> {\n        const ref = await this.project(projectId);\n        const workflows =\n            options.workflows && options.workflows.length > 0\n                ? options.workflows\n                : options.folder !== undefined\n                  ? await workflowsInFolder(ref.root, options.folder)\n                  : [];\n        if (workflows.length === 0)\n            throw new Error(\n                \"nothing to compose — pass workflows: [...] or a folder that holds workflow files\",\n            );\n        const registry = (await this.studio.registry.get()).registry;\n        // Composing a folder writes into THAT folder. The generic fallback\n        // uses the first part's directory, which for a recursive gather is\n        // some leaf several levels down, not the folder that was asked for.\n        const path =\n            options.path ??\n            (options.folder !== undefined\n                ? composedKeyForFolder(options.folder)\n                : undefined);\n        return composeWorkflows(ref.root, {\n            workflows,\n            ...(path !== undefined ? { path } : {}),\n            ...(options.name ? { name: options.name } : {}),\n            registry,\n        });\n    }\n\n    /** Generated files next to a workflow, with provenance. */\n    async workflowOutputs(\n        projectId: string,\n        keyInput: string,\n    ): Promise<OutputInfo[]> {\n        const ref = await this.project(projectId);\n        return listOutputs(ref.root, normalizeWorkflowKey(keyInput));\n    }\n\n    /** Save a document coming from the canvas (flow already edited client-side). */\n    async saveWorkflowDocument(\n        projectId: string,\n        keyInput: string,\n        doc: WorkflowDocument,\n    ): Promise<WorkflowSummary> {\n        const ref = await this.project(projectId);\n        const key = normalizeWorkflowKey(keyInput);\n        const store = hydrateStore(doc);\n        const registry = (await this.studio.registry.get()).registry;\n        await saveWorkflowFile(ref.root, key, store, {\n            registry,\n            meta: doc.meta,\n            name: doc.name,\n            description: doc.description ?? \"\",\n        });\n        return summarizeWorkflow(ref.root, key);\n    }\n\n    async deleteWorkflow(projectId: string, key: string): Promise<void> {\n        await deleteWorkflowFile(\n            (await this.project(projectId)).root,\n            normalizeWorkflowKey(key),\n        );\n    }\n\n    /* ---------------- billing checkpoint ---------------- */\n\n    /** How a plugin is billed, from what the registry knows about it. */\n    async pluginBilling(\n        pluginId: string,\n    ): Promise<{ billing: PluginBilling; note: string }> {\n        const { registry, meta } = await this.studio.registry.get();\n        const plugin = registry.plugins[pluginId] as\n            | { needsDeploy?: boolean }\n            | undefined;\n        const env = meta[pluginId]?.env ?? [];\n        if (plugin?.needsDeploy) {\n            return {\n                billing: \"modal\",\n                note: \"Runs on your Modal account: GPU time is billed per second while it runs (plus a cold start); the first run deploys the app, which can take minutes.\",\n            };\n        }\n        if (env.some((e) => e.required)) {\n            return {\n                billing: \"api\",\n                note: `Calls a paid API with your own key (${env\n                    .filter((e) => e.required)\n                    .map((e) => e.key)\n                    .join(\", \")}); every run is billed by that provider.`,\n            };\n        }\n        return {\n            billing: \"local\",\n            note: \"Runs locally / free of charge as far as the studio knows.\",\n        };\n    }\n\n    /**\n     * Paid plugins (API / Modal) a workflow run would use, with what the user\n     * needs to know to say yes. Empty means the run is free and may start\n     * without asking.\n     */\n    async paidPlugins(\n        projectId: string,\n        keyInput: string,\n    ): Promise<PluginConfirmation[]> {\n        const ref = await this.project(projectId);\n        const key = normalizeWorkflowKey(keyInput);\n        const doc = await readWorkflowFile(ref.root, key);\n        const nodes = doc.executable?.executableNodes ?? [];\n        const byPlugin = new Map<\n            string,\n            { slots: Set<string>; models: Set<string> }\n        >();\n        for (const n of nodes) {\n            if (!n.pluginId) continue;\n            const e = byPlugin.get(n.pluginId) ?? {\n                slots: new Set<string>(),\n                models: new Set<string>(),\n            };\n            e.slots.add(n.feature);\n            if (n.model) e.models.add(n.model);\n            byPlugin.set(n.pluginId, e);\n        }\n        if (byPlugin.size === 0) return [];\n        const { registry, meta } = await this.studio.registry.get();\n        const envNow = await this.studio.pluginEnv();\n        const out: PluginConfirmation[] = [];\n        for (const [pluginId, e] of byPlugin) {\n            const { billing, note } = await this.pluginBilling(pluginId);\n            if (billing === \"local\") continue;\n            const plugin = registry.plugins[pluginId] as\n                | {\n                      name?: string;\n                      methodsByNodeSlot?: Record<string, { models?: string[] }>;\n                  }\n                | undefined;\n            const slots = [...e.slots];\n            const availableModels = [\n                ...new Set(\n                    slots.flatMap(\n                        (slot) =>\n                            plugin?.methodsByNodeSlot?.[slot]?.models ?? [],\n                    ),\n                ),\n            ];\n            const alternatives: PluginConfirmation[\"alternatives\"] = [];\n            for (const [otherId, otherPlugin] of Object.entries(\n                registry.plugins,\n            )) {\n                if (otherId === pluginId) continue;\n                const shared = slots.filter(\n                    (slot) =>\n                        (\n                            otherPlugin as {\n                                methodsByNodeSlot?: Record<string, unknown>;\n                            }\n                        ).methodsByNodeSlot?.[slot],\n                );\n                if (shared.length === 0) continue;\n                alternatives.push({\n                    pluginId: otherId,\n                    billing: (await this.pluginBilling(otherId)).billing,\n                    slots: shared,\n                });\n            }\n            out.push({\n                pluginId,\n                ...(plugin?.name ? { name: plugin.name } : {}),\n                billing,\n                billingNote: note,\n                models: [...e.models],\n                availableModels,\n                env: (meta[pluginId]?.env ?? []).map((v) => ({\n                    key: v.key,\n                    required: Boolean(v.required),\n                    set: Boolean(envNow[v.key] || process.env[v.key]),\n                })),\n                slots,\n                alternatives,\n            });\n        }\n        return out;\n    }\n\n    /* ---------------- runs ---------------- */\n\n    async startRun(request: RunRequest): Promise<RunRecord> {\n        const project = await this.project(request.projectId);\n        const req: RunRequest = { ...request };\n        if (req.workflowKey)\n            req.workflowKey = normalizeWorkflowKey(req.workflowKey);\n        return this.studio.runs.start(project, req);\n    }\n\n    /** Canvas single-node execution → a run of a one-node inline document. */\n    async startCanvasRun(\n        projectId: string,\n        body: CanvasTaskBody,\n    ): Promise<RunRecord> {\n        const project = await this.project(projectId);\n        const document = await singleNodeDocument(project.root, body);\n        return this.studio.runs.start(project, {\n            projectId,\n            document,\n            label: `canvas ${body.feature}`,\n            keepRunDir: true,\n        });\n    }\n\n    getRun(runId: string): RunRecord | undefined {\n        return this.studio.runs.get(runId);\n    }\n\n    listRuns(projectId?: string) {\n        return this.studio.runs.list(projectId);\n    }\n\n    /** nodeId → status for the given workflow, from the latest run touching it. */\n    private nodeStatuses(\n        projectId: string,\n        key: string,\n    ): Record<string, string> {\n        const latest = this.studio.runs\n            .list(projectId)\n            .find((r) => r.workflow === key);\n        if (!latest) return {};\n        return Object.fromEntries(\n            Object.entries(latest.nodes).map(([id, n]) => [id, n.status]),\n        );\n    }\n\n    /* ---------------- plugins ---------------- */\n\n    async registry() {\n        return this.studio.registry.get();\n    }\n\n    async installPlugin(idOrUrl: string) {\n        return this.studio.registry.install(idOrUrl);\n    }\n\n    async uninstallPlugin(id: string) {\n        return this.studio.registry.uninstall(id);\n    }\n\n    async updatePlugins(ids?: string[]) {\n        return this.studio.registry.update(ids);\n    }\n\n    /**\n     * The node catalog the agent reads before writing a workflow: TongFlow's\n     * grammar (six node categories, how edges and outputs work, batch vs\n     * collect), then one line per node type grouped by category — ABI slot,\n     * wires (with the data node each accepts), config fields, outputs, and\n     * which installed plugins implement it. Everything per-type comes from\n     * the ABI registry, so it cannot drift from what the exporter accepts.\n     */\n    async nodeCatalog(): Promise<string> {\n        const { registry } = await this.studio.registry.get();\n        const byCat = new Map<NodeCategory, string[]>();\n        for (const c of NODE_CATEGORY_ORDER) byCat.set(c, []);\n        const uncategorized: string[] = [];\n        for (const type of KNOWN_NODE_TYPES) {\n            const cat = categoryOf(type);\n            const feature = NODE_TYPE_TO_ABI_FEATURE[type];\n            let line: string;\n            if (!feature) {\n                line =\n                    cat === \"add\"\n                        ? `- ${type}: canvas input widget — do NOT use in agent-written workflows; use the ${type.replace(/^add/, \"\").replace(/^[A-Z]/, (m) => m.toLowerCase())} modality node with data instead`\n                        : `- ${type}: carries ${type.replace(/Node$/, \"\")} (data: ${type === \"textNode\" || type === \"linkNode\" ? \"{texts:[…]}\" : \"{fileKeys:[…]}\"})`;\n            } else {\n                const spec = resolvedSpecForNodeType(type);\n                if (!spec) continue;\n                const wires: string[] = [];\n                const config: string[] = [];\n                for (const field of spec.topology.inputOrder) {\n                    const f = spec.fields[field];\n                    if (f.kind === \"handle\") {\n                        const flag = f.batch\n                            ? \" batch\"\n                            : f.collect\n                              ? \" collect\"\n                              : f.array\n                                ? \"[]\"\n                                : \"\";\n                        wires.push(\n                            `${field}←${f.nodeType.replace(/Node$/, \"\")}${flag}${f.required ? \"*\" : \"\"}`,\n                        );\n                    } else config.push(`${field}${f.required ? \"*\" : \"\"}`);\n                }\n                const outs = spec.topology.outputs.map(\n                    (o) => `${o.field}→${o.nodeType.replace(/Node$/, \"\")}`,\n                );\n                const plugins = registry.nodePluginMap[feature] ?? [];\n                line = `- ${type} (${feature}): wires ${wires.join(\", \") || \"-\"}; config ${config.join(\", \") || \"-\"}; out ${outs.join(\", \") || \"-\"}; plugins: ${plugins.length ? plugins.join(\", \") : \"NONE INSTALLED\"}`;\n            }\n            if (cat) byCat.get(cat)!.push(line);\n            else uncategorized.push(line);\n        }\n        const sections: string[] = [CATALOG_GRAMMAR.trim()];\n        const titles: Record<NodeCategory, string> = {\n            add: \"add/ — canvas input widgets (not for agent workflows)\",\n            modality:\n                \"modality/ — data nodes, one asset each (what you wire INTO executables; also what executables emit)\",\n            transfer: \"transfer/ — 1 → 1 executables\",\n            compose: \"compose/ — N → 1 executables\",\n            decompose: \"decompose/ — 1 → N executables\",\n            batch: \"batch/ — N → 1 groupings\",\n        };\n        for (const c of NODE_CATEGORY_ORDER) {\n            const lines = byCat.get(c) ?? [];\n            if (lines.length === 0) continue;\n            sections.push(`## ${titles[c]}\\n${lines.join(\"\\n\")}`);\n        }\n        if (uncategorized.length > 0)\n            sections.push(`## other\\n${uncategorized.join(\"\\n\")}`);\n        return sections.join(\"\\n\\n\");\n    }\n\n    /* ---------------- files & tree ---------------- */\n\n    async readTextFile(projectId: string, key: string): Promise<string> {\n        const ref = await this.project(projectId);\n        return readFile(fromProjectKey(ref.root, normalizeKey(key)), \"utf8\");\n    }\n\n    async writeTextFile(\n        projectId: string,\n        key: string,\n        text: string,\n    ): Promise<void> {\n        const ref = await this.project(projectId);\n        await writeFileAtomic(\n            fromProjectKey(ref.root, normalizeKey(key)),\n            text,\n        );\n    }\n\n    async deleteFile(projectId: string, key: string): Promise<void> {\n        const ref = await this.project(projectId);\n        await unlink(fromProjectKey(ref.root, normalizeKey(key)));\n    }\n\n    /**\n     * Store a user-supplied file under `dirKey` (created as needed) without\n     * overwriting: a clash gets a short suffix. Returns the project key.\n     */\n    async uploadFile(\n        projectId: string,\n        dirKey: string,\n        fileName: string,\n        data: Uint8Array,\n    ): Promise<{ key: string; size: number }> {\n        const ref = await this.project(projectId);\n        const dir = fromProjectKey(ref.root, normalizeKey(dirKey) || \".\");\n        await mkdir(dir, { recursive: true });\n        const safe =\n            sanitizeFileName(basename(fileName || \"upload\")) || \"upload\";\n        let dest = join(dir, safe);\n        if (await exists(dest)) {\n            const ext = safe.includes(\".\")\n                ? safe.slice(safe.lastIndexOf(\".\"))\n                : \"\";\n            const stem = safe.slice(0, safe.length - ext.length);\n            let i = 2;\n            while (await exists(join(dir, `${stem}-${i}${ext}`))) i++;\n            dest = join(dir, `${stem}-${i}${ext}`);\n        }\n        await writeFile(dest, data);\n        return { key: toProjectKey(ref.root, dest), size: data.byteLength };\n    }\n\n    async filePath(projectId: string, key: string): Promise<string> {\n        const ref = await this.project(projectId);\n        return fromProjectKey(ref.root, normalizeKey(key));\n    }\n\n    /**\n     * The project folder as a tree. Generated files (`<stem>.NN…`) and the\n     * runs log are nested under their workflow so the pane shows \"workflow +\n     * what it made\" as one unit; everything else is listed as-is.\n     */\n    async tree(projectId: string): Promise<TreeNode[]> {\n        const ref = await this.project(projectId);\n        return this.dirTree(ref.root, ref.root, \"\");\n    }\n\n    private async dirTree(\n        root: string,\n        dir: string,\n        prefix: string,\n    ): Promise<TreeNode[]> {\n        if (!(await exists(dir))) return [];\n        const entries = (await readdir(dir, { withFileTypes: true })).filter(\n            (e) => !e.name.startsWith(\".\") && e.name !== RUNS_DIR,\n        );\n        entries.sort((a, b) => {\n            if (a.isDirectory() !== b.isDirectory())\n                return a.isDirectory() ? -1 : 1;\n            return a.name.localeCompare(b.name);\n        });\n        const keyOf = (name: string) => (prefix ? `${prefix}/${name}` : name);\n        // Outputs claimed by a workflow in this directory are hidden from the flat list.\n        const claimed = new Set<string>();\n        const workflowNodes = new Map<string, TreeNode>();\n        for (const e of entries) {\n            if (!e.isFile() || !isWorkflowKey(e.name)) continue;\n            const key = keyOf(e.name);\n            const outputs = await listOutputs(root, key);\n            const logKey = runsLogKey(key);\n            const children: TreeNode[] = outputs.map((o) => {\n                claimed.add(o.fileName);\n                return {\n                    id: o.key,\n                    label: o.fileName.slice(\n                        basename(key, WORKFLOW_EXT).length + 1,\n                    ),\n                    kind: \"output\" as const,\n                    key: o.key,\n                    meta: {\n                        size: o.size,\n                        mtime: o.mtime,\n                        modality: modalityOfExt(o.ext),\n                        no: o.no,\n                        ...(o.output ? { output: o.output } : {}),\n                    },\n                };\n            });\n            claimed.add(basename(logKey));\n            const st = await stat(join(dir, e.name));\n            workflowNodes.set(e.name, {\n                id: key,\n                label: e.name.slice(0, -WORKFLOW_EXT.length),\n                kind: \"workflow\",\n                key,\n                meta: {\n                    size: st.size,\n                    mtime: st.mtime.toISOString(),\n                    outputCount: outputs.length,\n                },\n                ...(children.length > 0 ? { children } : {}),\n            });\n        }\n        const out: TreeNode[] = [];\n        for (const e of entries) {\n            const key = keyOf(e.name);\n            if (e.isDirectory()) {\n                out.push({\n                    id: key,\n                    label: e.name,\n                    kind: \"folder\",\n                    key,\n                    children: await this.dirTree(root, join(dir, e.name), key),\n                });\n                continue;\n            }\n            const wf = workflowNodes.get(e.name);\n            if (wf) {\n                out.push(wf);\n                continue;\n            }\n            if (claimed.has(e.name)) continue;\n            const st = await stat(join(dir, e.name));\n            out.push({\n                id: key,\n                label: e.name,\n                kind: \"file\",\n                key,\n                meta: {\n                    size: st.size,\n                    mtime: st.mtime.toISOString(),\n                    modality: modalityOfExt(e.name.split(\".\").pop() ?? \"\"),\n                },\n            });\n        }\n        return out;\n    }\n\n    /** Provenance log of a workflow (`<stem>.runs.json`). */\n    async runsLog(projectId: string, keyInput: string) {\n        const ref = await this.project(projectId);\n        return readRunsLog(ref.root, normalizeWorkflowKey(keyInput));\n    }\n\n    toKey(projectRoot: string, abs: string): string {\n        return toProjectKey(projectRoot, abs);\n    }\n}\n\n/** Keep a user-supplied file name safe for the project folder: no control chars, no separators, no leading dots. */\nfunction sanitizeFileName(name: string): string {\n    const cleaned = [...name]\n        .map((ch) =>\n            ch.charCodeAt(0) < 32 || '/\\\\:*?\"<>|'.includes(ch) ? \"_\" : ch,\n        )\n        .join(\"\")\n        .replace(/\\s+/g, \"_\")\n        .replace(/^\\.+/, \"\");\n    return cleaned;\n}\n\n/** The grammar preamble of the node catalog. */\nconst CATALOG_GRAMMAR = `\n# TongFlow node grammar (follow it exactly — the patch tool rejects anything else)\n\nA workflow is a graph of MODALITY data nodes and EXECUTABLE nodes.\n- Modality nodes (textNode, imageNode, videoNode, audioNode, fileNode, modelNode, linkNode) carry one asset each: data:{texts:[…]} for text/link, data:{fileKeys:[…]} for the others (paths relative to the workflow file or the project root, or URLs). They are the ONLY things you wire into an executable.\n- Executable nodes come in four categories (each maps to one ABI slot = one plugin method): transfer (1 → 1), compose (N → 1), decompose (1 → N), batch (N → 1 grouping). Pick the node whose slot matches the transformation; never fake a compose with a chain of transfers or vice versa.\n- Each executable's \"wires\" are its input handles: field←modality (* = required). Draw an edge FROM a modality node (or an upstream executable's output) TO that field; handles are derived automatically, pass toHandle only to disambiguate. Its \"config\" fields are set in data:{…} at creation or by update_nodes. Its \"out\" lists the modality nodes it emits — those are created automatically when you save; wire the NEXT executable from the executable node itself (or its emitted modality node), never invent an output node.\n- Batch semantics: a wire marked \"batch\" runs the executable once per upstream item (a textNode with 3 texts → 3 outputs); \"collect\" gathers every incoming edge into one array for a single run (e.g. images collect → one video); \"[]\" is an intrinsically array-typed input. Do not build loops by copying nodes — use batch.\n- Level-0 modality nodes WITHOUT data become workflow inputs supplied at run time (name them with data:{inputName:'…'}); prefer writing the data in.\n- Text you author goes into textNode data (or {{file}} includes) — genTextNode / textsGenTextNode are for mechanical transforms only.\n- After every patch read the result: ok:false steps mean the grammar or ABI rejected it — fix, do not retry blindly. tongflow_node_describe(type) gives the full config schema (enums, ranges, defaults) of one node.\n`;\n\n/** Indented text view of the tree (what the agent reads in project_status). */\nexport function renderTree(nodes: TreeNode[], depth = 0): string {\n    const lines: string[] = [];\n    for (const n of nodes) {\n        const pad = \"  \".repeat(depth);\n        if (n.kind === \"folder\") {\n            lines.push(`${pad}${n.label}/`);\n            if (n.children) lines.push(renderTree(n.children, depth + 1));\n        } else if (n.kind === \"workflow\") {\n            const count = n.meta?.outputCount ?? 0;\n            lines.push(\n                `${pad}${n.label}${WORKFLOW_EXT}  [workflow${count ? `, ${count} output file${count === 1 ? \"\" : \"s\"}` : \"\"}]`,\n            );\n            for (const c of n.children ?? [])\n                lines.push(`${pad}  ${c.key.split(\"/\").pop()}`);\n        } else if (n.kind === \"file\") {\n            lines.push(`${pad}${n.label}`);\n        }\n    }\n    return lines.filter((l) => l.length > 0).join(\"\\n\");\n}\n"
    },
